//! Whole immutable original requirement policy comparison.
use crate::lint::Registry;
#[path="../fixtures/original_policies/requirement_bool_workspace.rs"]mod original;
#[path="../fixtures/native-requirement-bool-workspace/fixture.rs"]mod fixture;
#[path="../../dmb/shared/test_scratch.rs"]mod scratch;
fn record(outcome:&crate::run::Outcome)->serde_json::Value{serde_json::json!({"sites":outcome.run.sites,"notes":outcome.run.notes,"allow_used":outcome.allow_used,"failed":outcome.failed,"text":outcome.text})}
#[test]fn shared_requirement_bool_preserves_entire_original_typed_raw_union_macro_order_and_exemptions(){for case in fixture::CASES{let root=scratch::dir(&format!("requirement-whole-{case}"));for(relative,bytes)in fixture::files(case){let path=root.join(relative);std::fs::create_dir_all(path.parent().unwrap()).unwrap();std::fs::write(path,bytes).unwrap();}let options=crate::run::Options{root,lints:vec!["requirement_bool".into()],no_cache:true,raw:true,..Default::default()};let mut old_reg=Registry::default();original::register(&mut old_reg);let old=crate::run::Engine::new(old_reg,options.clone()).unwrap();let sem=crate::sem::sem_for(&old.tree).unwrap();assert!(sem.errors.is_empty(),"original parser errors: {:?}",sem.errors);let mut current_reg=Registry::default();crate::lints::requirement_bool::register(&mut current_reg);let current=crate::run::Engine::new(current_reg,options).unwrap();let before=old.run_one(old.reg.lints[0].as_ref());let original_scope=old.scopes.for_lint("requirement_bool","");assert_eq!(original_scope.exempt("code/probe.dm"),*case=="exempt","the ORIGINAL config loader must observe the intended exemption");if *case=="exempt"{assert!(before.run.sites.is_empty(),"actual immutable original omits exempt typed and raw requirement calls");}else{assert!(!before.run.sites.is_empty(),"actual original positive control");}let after=current.run_one(current.reg.lints[0].as_ref());assert_eq!(record(&before),record(&after),"entire unchanged original result for {case}");println!("SHARED_REQUIREMENT_BOOL_OLD={}",serde_json::json!({"case":case,"record":record(&before),"source_text":before.run.sites.iter().map(|site|old.tree.site_text(&site.rel,site.line as usize)).collect::<Vec<_>>()}));}}
